struct Control{HWND h;int x,y,w,height;};
struct App {HWND window=nullptr;HINSTANCE instance=nullptr;HFONT font=nullptr;Document doc=create();std::wstring path,root;std::vector<Control> controls;std::array<HWND,UIntCount> ints{};std::array<HWND,FloatCount> floats{};std::array<HWND,3> names{};std::array<HWND,12> checks{};HWND soc=nullptr,status=nullptr;bool dirty=false,loading=false;int scroll=0;};
std::wstring wide(const std::string&s,UINT cp=CP_UTF8){if(s.empty())return {};int n=MultiByteToWideChar(cp,0,s.data(),int(s.size()),nullptr,0);std::wstring r(n,0);MultiByteToWideChar(cp,0,s.data(),int(s.size()),r.data(),n);return r;}
std::string ansi(const std::wstring&s){if(s.empty())return {};BOOL used=FALSE;int n=WideCharToMultiByte(1251,WC_NO_BEST_FIT_CHARS,s.data(),int(s.size()),nullptr,0,nullptr,&used);std::string r(n,0);WideCharToMultiByte(1251,WC_NO_BEST_FIT_CHARS,s.data(),int(s.size()),r.data(),n,nullptr,&used);if(used)throw std::runtime_error("THM paths must be representable in Windows-1251");return r;}
std::wstring settingsPath(){wchar_t dir[MAX_PATH]{};if(FAILED(SHGetFolderPathW(nullptr,CSIDL_APPDATA|CSIDL_FLAG_CREATE,nullptr,0,dir)))throw std::runtime_error("AppData unavailable");std::wstring p=std::wstring(dir)+L"\\XRayTHMTools";fs::create_directories(p);return p+L"\\editor.ini";}
std::wstring setting(const wchar_t* key){wchar_t buf[32768]{};GetPrivateProfileStringW(L"Editor",key,L"",buf,32768,settingsPath().c_str());return buf;}
void setSetting(const wchar_t* key,const std::wstring& value){if(!WritePrivateProfileStringW(L"Editor",key,value.c_str(),settingsPath().c_str()))throw std::runtime_error("Cannot save editor preferences");}
void pickFallback(App&a){std::vector<wchar_t> buffer(32768);OPENFILENAMEW ofn{};ofn.lStructSize=sizeof(ofn);ofn.hwndOwner=a.window;ofn.lpstrFile=buffer.data();ofn.nMaxFile=DWORD(buffer.size());ofn.lpstrFilter=L"Programs\0*.exe\0\0";ofn.Flags=OFN_EXPLORER|OFN_FILEMUSTEXIST|OFN_NOCHANGEDIR;if(!GetOpenFileNameW(&ofn))return;wchar_t self[32768]{};GetModuleFileNameW(nullptr,self,32768);if(_wcsicmp(self,buffer.data())==0)throw std::runtime_error("Choose your previous editor, not XRayTHMEditor.exe");setSetting(L"FallbackEditor",buffer.data());}
int fallback(const std::wstring& file){auto program=setting(L"FallbackEditor");if(program.empty()){wchar_t sys[MAX_PATH]{};GetSystemDirectoryW(sys,MAX_PATH);program=std::wstring(sys)+L"\\notepad.exe";}wchar_t self[32768]{};GetModuleFileNameW(nullptr,self,32768);if(_wcsicmp(self,program.c_str())==0)throw std::runtime_error("Fallback editor points to itself");std::wstring args=L"\""+file+L"\"";SHELLEXECUTEINFOW sh{};sh.cbSize=sizeof(sh);sh.fMask=SEE_MASK_NOCLOSEPROCESS;sh.lpFile=program.c_str();sh.lpParameters=args.c_str();sh.nShow=SW_SHOWNORMAL;if(!ShellExecuteExW(&sh))throw std::runtime_error("Cannot start fallback editor");if(sh.hProcess){WaitForSingleObject(sh.hProcess,INFINITE);CloseHandle(sh.hProcess);}return 0;}
std::wstring text(HWND h){int n=GetWindowTextLengthW(h);std::wstring s(size_t(n)+1,0);GetWindowTextW(h,s.data(),n+1);s.resize(n);return s;}
std::string numeric(HWND h){auto s=text(h);auto p=s.find(L" : ");if(p!=s.npos)s.resize(p);return std::string(s.begin(),s.end());}
std::wstring hex(uint32_t n){std::wostringstream s;s<<L"0x"<<std::hex<<std::uppercase<<std::setw(8)<<std::setfill(L'0')<<n;return s.str();}
void error(App&a,const std::exception&e){MessageBoxW(a.window,wide(e.what()).c_str(),L"X-Ray THM Editor",MB_ICONERROR);}
void title(App&a){auto t=(a.dirty?L"* ":L"")+std::wstring(L"X-Ray THM Editor 0.4.0-beta — ")+(a.path.empty()?L"Новый THM":fs::path(a.path).filename().wstring());SetWindowTextW(a.window,t.c_str());}
HWND add(App&a,const wchar_t* cls,const wchar_t* label,DWORD style,int id,int x,int y,int w,int h){auto c=CreateWindowExW(wcscmp(cls,L"EDIT")==0?WS_EX_CLIENTEDGE:0,cls,label,WS_CHILD|WS_VISIBLE|style,x,y,w,h,a.window,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),a.instance,nullptr);if(!c)throw std::runtime_error("Cannot create editor control");SendMessageW(c,WM_SETFONT,reinterpret_cast<WPARAM>(a.font),TRUE);a.controls.push_back({c,x,y,w,h});return c;}
void fillFlags(App&a,uint32_t mask){a.loading=true;for(size_t i=0;i<a.checks.size();i++)SendMessageW(a.checks[i],BM_SETCHECK,(mask&(1u<<flag_list()[i].bit))?BST_CHECKED:BST_UNCHECKED,0);a.loading=false;}
void populate(App&a){a.loading=true;for(int i=0;i<UIntCount;i++){auto choices=enum_names(UIntField(i));std::wstring v;if(!choices.empty())v=std::to_wstring(a.doc.current.u[i])+L" : "+wide(enum_name(UIntField(i),a.doc.current.u[i]));else v=(i==Flags||i==BorderColor||i==FadeColor)?hex(a.doc.current.u[i]):std::to_wstring(a.doc.current.u[i]);SetWindowTextW(a.ints[i],v.c_str());}
 for(int i=0;i<FloatCount;i++)SetWindowTextW(a.floats[i],wide(float_text(a.doc.current.f[i])).c_str());for(int i=0;i<3;i++)SetWindowTextW(a.names[i],wide(a.doc.current.names[i],1251).c_str());SendMessageW(a.soc,BM_SETCHECK,a.doc.current.soc?BST_CHECKED:BST_UNCHECKED,0);SetWindowTextW(a.status,a.path.empty()?L"Новый документ. Сохранение создаст файл THM.":a.path.c_str());a.loading=false;fillFlags(a,a.doc.current.u[Flags]);title(a);}
Settings collect(App&a){auto t=a.doc.current;for(int i=0;i<UIntCount;i++)t.u[i]=parse_uint(numeric(a.ints[i]));for(int i=0;i<FloatCount;i++)t.f[i]=parse_float(numeric(a.floats[i]));for(int i=0;i<3;i++)t.names[i]=ansi(text(a.names[i]));t.soc=SendMessageW(a.soc,BM_GETCHECK,0,0)==BST_CHECKED;auto temp=a.doc;temp.current=t;(void)serialize(temp);return t;}
std::wstring dialog(App&a,bool save,bool dds=false,const std::wstring& initial=L""){std::vector<wchar_t> buffer(32768);if(!initial.empty())wcsncpy_s(buffer.data(),buffer.size(),initial.c_str(),_TRUNCATE);OPENFILENAMEW ofn{};ofn.lStructSize=sizeof(ofn);ofn.hwndOwner=a.window;ofn.lpstrFile=buffer.data();ofn.nMaxFile=DWORD(buffer.size());ofn.lpstrFilter=dds?L"DDS textures\0*.dds\0\0":L"THM files\0*.thm\0\0";ofn.lpstrDefExt=dds?L"dds":L"thm";ofn.Flags=OFN_EXPLORER|OFN_PATHMUSTEXIST|OFN_NOCHANGEDIR|(save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);if(save?GetSaveFileNameW(&ofn):GetOpenFileNameW(&ofn))return buffer.data();return {};}
bool exists(const std::wstring&p){return GetFileAttributesW(p.c_str())!=INVALID_FILE_ATTRIBUTES;}
void save(App&a,bool as){auto t=collect(a);auto dest=(as||a.path.empty())?dialog(a,true,false,a.path):a.path;if(dest.empty())return;auto copy=a.doc;copy.current=t;auto bytes=serialize(copy);bool same=!a.path.empty()&&_wcsicmp(dest.c_str(),a.path.c_str())==0;std::vector<uint8_t> snapshot;const std::vector<uint8_t>* expected=nullptr;if(same)expected=&a.doc.original;else if(exists(dest)){snapshot=read_bytes(dest);expected=&snapshot;}
 if(same&&bytes==a.doc.original){if(read_bytes(dest)!=a.doc.original)throw std::runtime_error("File changed on disk. Reopen before saving.");a.dirty=false;title(a);return;}
 auto backup=save_atomic(dest,bytes,expected);a.doc=load(bytes);a.path=dest;a.dirty=false;populate(a);SetWindowTextW(a.status,backup.empty()?L"Сохранено.":(L"Сохранено. Резервная копия: "+backup).c_str());}
bool leave(App&a){if(!a.dirty)return true;int n=MessageBoxW(a.window,L"Сохранить изменения?",L"X-Ray THM Editor",MB_YESNOCANCEL|MB_ICONQUESTION);if(n==IDCANCEL)return false;if(n==IDYES){save(a,false);return !a.dirty;}return true;}
std::wstring sidecar(const std::wstring&p){fs::path f(p);if(_wcsicmp(f.extension().c_str(),L".dds")==0)f.replace_extension(L".thm");return f.wstring();}
void open(App&a,const std::wstring&p){auto file=sidecar(p);auto d=load(read_bytes(file));a.doc=std::move(d);a.path=file;a.dirty=false;populate(a);}
std::string gameName(App&a,const std::wstring&file){std::wstring path=fs::absolute(fs::path(file)).lexically_normal().wstring(),root=a.root;if(root.empty()){auto lower=path;std::transform(lower.begin(),lower.end(),lower.begin(),[](wchar_t c){return towlower(c);});size_t at=lower.rfind(L"\\textures\\");if(at!=lower.npos)root=path.substr(0,at+9);}
 if(root.empty())throw std::runtime_error("Select the textures root folder in Tools, or type the relative texture name manually.");auto rel=fs::path(path).lexically_relative(fs::absolute(fs::path(root)).lexically_normal());if(rel.empty()||rel.is_absolute()||*rel.begin()==L"..")throw std::runtime_error("Texture must be inside the configured textures root folder");rel.replace_extension();return ansi(rel.wstring());}
void pickRoot(App&a){BROWSEINFOW b{};b.hwndOwner=a.window;b.lpszTitle=L"Выберите корневую папку textures";b.ulFlags=BIF_RETURNONLYFSDIRS|BIF_NEWDIALOGSTYLE;auto id=SHBrowseForFolderW(&b);if(id){wchar_t p[MAX_PATH];if(SHGetPathFromIDListW(id,p)){a.root=p;setSetting(L"TexturesRoot",a.root);}CoTaskMemFree(id);}}
void browseMap(App&a,int i){auto p=dialog(a,false,true);if(p.empty())return;SetWindowTextW(a.names[i],wide(gameName(a,p),1251).c_str());a.dirty=true;title(a);}
void import(App&a){auto p=dialog(a,false,true);if(p.empty())return;auto t=collect(a);auto dd=read_dds_header(read_header(p));import_dds(t,dd);fs::path bump=fs::path(p).parent_path()/(fs::path(p).stem().wstring()+L"_bump.dds");if(exists(bump.wstring())){t.names[1]=gameName(a,bump.wstring());t.u[BumpMode]=2;}a.doc.current=t;a.dirty=true;populate(a);if(!dd.warning.empty())MessageBoxW(a.window,wide(dd.warning).c_str(),L"DDS",MB_ICONINFORMATION);}
void generate(App&a){if(!leave(a))return;auto p=dialog(a,false,true);if(p.empty())return;auto main=create();main.current.u[Flags]=1u<<8;auto dd=read_dds_header(read_header(p));if(dd.format<0)throw std::runtime_error("DDS format cannot be mapped to classic THM. Use New + Import DDS and select the format manually.");import_dds(main.current,dd);
 fs::path input(p),bump=input.parent_path()/(input.stem().wstring()+L"_bump.dds");std::vector<std::pair<std::wstring,Document>> files;
 if(exists(bump.wstring())){main.current.names[1]=gameName(a,bump.wstring());main.current.u[BumpMode]=2;auto b=create();b.current.u[Flags]=(1u<<8)|(1u<<25);auto bd=read_dds_header(read_header(bump.wstring()));if(bd.format<0)throw std::runtime_error("Bump DDS format cannot be mapped to THM");import_dds(b.current,bd);b.current.u[Type]=2;auto target=bump;target.replace_extension(L".thm");files.push_back({target.wstring(),b});}
 auto mainPath=input;mainPath.replace_extension(L".thm");files.insert(files.begin(),{mainPath.wstring(),main});
 std::wstring question=L"Создать следующие THM? Существующие файлы будут заменены с резервной копией.\n\n";for(auto& f:files)question+=f.first+L"\n";if(!dd.warning.empty())question+=L"\n"+wide(dd.warning);if(MessageBoxW(a.window,question.c_str(),L"Генерация THM",MB_OKCANCEL|MB_ICONQUESTION)!=IDOK)return;
 std::vector<std::vector<uint8_t>> payloads,snapshots;std::vector<bool> present;for(auto& f:files){payloads.push_back(serialize(f.second));present.push_back(exists(f.first));snapshots.push_back(present.back()?read_bytes(f.first):std::vector<uint8_t>{});}
 size_t done=0;try{for(size_t i=0;i<files.size();i++){save_atomic(files[i].first,payloads[i],present[i]?&snapshots[i]:nullptr);done++;}}catch(const std::exception&e){throw std::runtime_error(std::string(e.what())+"; files saved before failure: "+std::to_string(done)+". Existing files have backup copies.");}
 open(a,mainPath.wstring());}
void pickColor(App&a,UIntField field){auto old=parse_uint(numeric(a.ints[field]));static COLORREF custom[16]{};CHOOSECOLORW cc{};cc.lStructSize=sizeof(cc);cc.hwndOwner=a.window;cc.rgbResult=RGB((old>>16)&255,(old>>8)&255,old&255);cc.lpCustColors=custom;cc.Flags=CC_FULLOPEN|CC_RGBINIT;if(ChooseColorW(&cc)){uint32_t rgb=(uint32_t(GetRValue(cc.rgbResult))<<16)|(uint32_t(GetGValue(cc.rgbResult))<<8)|GetBValue(cc.rgbResult);SetWindowTextW(a.ints[field],hex((old&0xff000000u)|rgb).c_str());}}
void removeVerb(App&a){auto result=RegDeleteTreeW(HKEY_CURRENT_USER,L"Software\\Classes\\SystemFileAssociations\\.thm\\shell\\XRayTHMEdit");if(result!=ERROR_SUCCESS&&result!=ERROR_FILE_NOT_FOUND)throw std::runtime_error("Cannot remove context menu command");SHChangeNotify(SHCNE_ASSOCCHANGED,SHCNF_IDLIST,nullptr,nullptr);}
void registerVerb(App&a){if(MessageBoxW(a.window,L"Добавить команду «Редактировать THM» в контекстное меню .thm для текущего пользователя?",L"Интеграция",MB_OKCANCEL)!=IDOK)return;wchar_t exe[32768]{};GetModuleFileNameW(nullptr,exe,32768);HKEY k=nullptr;auto path=L"Software\\Classes\\SystemFileAssociations\\.thm\\shell\\XRayTHMEdit";if(RegCreateKeyExW(HKEY_CURRENT_USER,path,0,nullptr,0,KEY_SET_VALUE,nullptr,&k,nullptr)!=ERROR_SUCCESS)throw std::runtime_error("Cannot create edit verb");const wchar_t* label=L"Редактировать THM";LONG labelResult=RegSetValueExW(k,nullptr,0,REG_SZ,reinterpret_cast<const BYTE*>(label),DWORD((wcslen(label)+1)*2));RegCloseKey(k);if(labelResult!=ERROR_SUCCESS)throw std::runtime_error("Cannot write edit label");std::wstring sub=std::wstring(path)+L"\\command";if(RegCreateKeyExW(HKEY_CURRENT_USER,sub.c_str(),0,nullptr,0,KEY_SET_VALUE,nullptr,&k,nullptr)!=ERROR_SUCCESS)throw std::runtime_error("Cannot create command");std::wstring cmd=L"\""+std::wstring(exe)+L"\" \"%1\"";LONG err=RegSetValueExW(k,nullptr,0,REG_SZ,reinterpret_cast<const BYTE*>(cmd.c_str()),DWORD((cmd.size()+1)*2));RegCloseKey(k);if(err!=ERROR_SUCCESS)throw std::runtime_error("Cannot write edit command");SHChangeNotify(SHCNE_ASSOCCHANGED,SHCNF_IDLIST,nullptr,nullptr);}
void action(App&a,int id){switch(id){case New:if(leave(a)){a.doc=create();a.path.clear();a.dirty=true;populate(a);}break;case Open:if(leave(a)){auto p=dialog(a,false);if(!p.empty())open(a,p);}break;case Save:save(a,false);break;case SaveAs:save(a,true);break;case Exit:SendMessageW(a.window,WM_CLOSE,0,0);break;case Import:import(a);break;case Generate:generate(a);break;case TypePreset:a.doc.current=collect(a);apply_type_defaults(a.doc.current);a.dirty=true;populate(a);break;case FlagDefaults:{auto mask=parse_uint(numeric(a.ints[Flags]));for(const auto&f:flag_list())mask&=~(1u<<f.bit);mask|=1u|(1u<<8);SetWindowTextW(a.ints[Flags],hex(mask).c_str());fillFlags(a,mask);a.dirty=true;title(a);break;}case Root:pickRoot(a);break;case Fallback:pickFallback(a);break;case RegisterVerb:registerVerb(a);break;case RemoveVerb:removeVerb(a);break;case About:MessageBoxW(a.window,L"X-Ray THM Editor 0.4.0-beta\n\nNative editor for texture THM.\nField definitions and feature reference: THM-Editor by VaIeroK, i-love-kfc; chunk reader credit: mortany.\n\nUnknown chunks are preserved. Backups are made on overwrite.",L"О программе",MB_OK);break;}}
void layout(App&a){RECT r{};GetClientRect(a.window,&r);int page=r.bottom;int max=std::max(0,655-page);a.scroll=std::clamp(a.scroll,0,max);SCROLLINFO si{sizeof(si),SIF_RANGE|SIF_PAGE|SIF_POS,0,654,UINT(std::max(1,page)),a.scroll,0};SetScrollInfo(a.window,SB_VERT,&si,TRUE);for(auto c:a.controls)MoveWindow(c.h,c.x,c.y-a.scroll,c.w,c.height,TRUE);}
